import {
  encodeDeployData,
  encodeFunctionData,
  getAddress,
  getContractAddress,
  keccak256,
  parseAbi,
  stringToHex,
  type Address,
  type Hex,
} from "viem";

import {
  SINGLETON_FACTORY_ADDRESS,
  singletonFactoryAbi,
} from "./standing-order-batch-executor.js";

export const FWA_SEQUENCE_EXECUTOR_SALT = keccak256(
  stringToHex("pull-pool-keeper/FwaSequenceExecutor/v1"),
);
export const FWA_SEQUENCE_EXECUTOR_DEPLOY_GAS_LIMIT = 450_000n;

export const fwaSequenceExecutorAbi = parseAbi([
  "constructor(address owner)",
  "function FWA() view returns (address)",
  "function owner() view returns (address)",
  "function processExact(uint64 expectedNext,uint64 expectedAfter) returns (uint256 processed)",
  "event ExactSequenceProcessed(uint64 indexed firstSequence,uint64 indexed afterSequence,uint256 processed)",
  "error EmptyInterval()",
  "error InvalidOwner()",
  "error ProcessingIncomplete(uint256 expectedCount,uint256 processed,uint64 expectedAfter,uint64 actualAfter)",
  "error ProcessorMoved(uint64 expected,uint64 actual)",
  "error Unauthorized()",
]);

// Generated from solc 0.8.28, Cancun, optimizer enabled with 1,000,000 runs.
export const FWA_SEQUENCE_EXECUTOR_BYTECODE = "" as Hex;
const FWA_SEQUENCE_EXECUTOR_RUNTIME_TEMPLATE = "" as Hex;
const OWNER_IMMUTABLE_OFFSETS = [141, 233] as const;

function patchOwnerImmutable(template: Hex, owner: Address): Hex {
  const ownerWord = owner.slice(2).padStart(64, "0");
  let body = template.slice(2);
  for (const offset of OWNER_IMMUTABLE_OFFSETS) {
    const start = offset * 2;
    body = `${body.slice(0, start)}${ownerWord}${body.slice(start + 64)}`;
  }
  return `0x${body}`;
}

export function fwaSequenceExecutorDeployment(owner: Address): {
  readonly initCode: Hex;
  readonly address: Address;
  readonly expectedRuntimeCode: Hex;
  readonly expectedRuntimeCodeHash: Hex;
  readonly deployData: Hex;
} {
  const canonicalOwner = getAddress(owner);
  const initCode = encodeDeployData({
    abi: fwaSequenceExecutorAbi,
    bytecode: FWA_SEQUENCE_EXECUTOR_BYTECODE,
    args: [canonicalOwner],
  });
  const address = getContractAddress({
    from: SINGLETON_FACTORY_ADDRESS,
    opcode: "CREATE2",
    salt: FWA_SEQUENCE_EXECUTOR_SALT,
    bytecode: initCode,
  });
  const expectedRuntimeCode = patchOwnerImmutable(
    FWA_SEQUENCE_EXECUTOR_RUNTIME_TEMPLATE,
    canonicalOwner,
  );
  return {
    initCode,
    address,
    expectedRuntimeCode,
    expectedRuntimeCodeHash: keccak256(expectedRuntimeCode),
    deployData: encodeFunctionData({
      abi: singletonFactoryAbi,
      functionName: "deploy",
      args: [initCode, FWA_SEQUENCE_EXECUTOR_SALT],
    }),
  };
}

export function encodeExactFwaSequenceProcessing(
  expectedNext: bigint,
  processCount: bigint,
): Hex {
  if (expectedNext < 0n || processCount <= 0n) {
    throw new Error("exact FWA sequence interval must be positive");
  }
  const expectedAfter = expectedNext + processCount;
  if (expectedAfter > 0xffff_ffff_ffff_ffffn) {
    throw new Error("exact FWA sequence interval exceeds uint64");
  }
  return encodeFunctionData({
    abi: fwaSequenceExecutorAbi,
    functionName: "processExact",
    args: [expectedNext, expectedAfter],
  });
}
